import type { Doc, Id, QueryCtx } from "@wizard/sdk";

type Status = Doc<"cake_order">["status"];

/** Неоплаченный заказ держит место в производственном дне 30 минут — столько живёт платёж ЮKassa. */
export const HOLD_MINUTES = 30;
/** Заказы, которые занимают производство; отменённые и возвращённые место освобождают. */
const BUSY: readonly Status[] = ["prepaid", "in_production", "ready", "completed"];

/**
 * Сколько тортов уже стоит на производственный день. Считает по всем заказам, поэтому нужен
 * systemDb (покупатель видит только свои); наружу отдаётся только число, без ПДн.
 */
export async function taken(ctx: Pick<QueryCtx, "systemDb" | "now">, slot: Id<"production_slot">): Promise<number> {
  let n = 0;
  for (const status of BUSY) n += await ctx.systemDb.cake_order.count({ where: { slot, status } });
  const since = new Date(ctx.now.getTime() - HOLD_MINUTES * 60_000).toISOString();
  const pending = await ctx.systemDb.cake_order.list({ where: { slot, status: "pending_payment" }, limit: 1000 });
  return n + pending.filter((o) => o.created_at >= since).length;
}

/** Дата YYYY-MM-DD по Москве: производственный день кондитерской. */
export function moscowDate(d: Date, plusDays = 0): string {
  const shifted = new Date(d.getTime() + plusDays * 86_400_000);
  return new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Moscow" }).format(shifted);
}

import type { Doc, Id, QueryCtx } from "@wizard/sdk";

type Option = Doc<"product_option">;
export type OptionGroup = Option["option_group"];

/** Порядок групп в чеке; вес и начинка — ровно по одной, декор — сколько угодно. */
export const GROUPS: readonly OptionGroup[] = ["weight", "filling", "decor"];
const REQUIRED: Readonly<Record<OptionGroup, string | null>> = {
  weight: "Выберите вес",
  filling: "Выберите начинку",
  decor: null,
};

export type PriceLine = { id: Id<"product_option">; group: OptionGroup; title: string; price: number };

export interface Quote {
  lines: PriceLine[];
  /** Группы, в которых не выбран обязательный вариант; оформить заказ можно только при пустом списке. */
  missing: OptionGroup[];
  total: number;
  /** Предоплата 50%; нечётная копейка — в предоплату. */
  prepay: number;
  remaining: number;
}

const toKop = (rub: number) => Math.round(rub * 100);

/**
 * Цена считается только здесь (ui-kit.yaml#ItemCard: итог — от сервера). Опции читаются через ctx.db,
 * то есть с правами вызывающего: витрина открыта посетителю, скрытых полей у опций нет.
 */
export async function quote(
  ctx: Pick<QueryCtx, "db" | "error">,
  productId: Id<"product">,
  optionIds: readonly Id<"product_option">[],
): Promise<Quote> {
  const product = await ctx.db.product.get(productId);
  if (!product || product.active === false) {
    throw ctx.error("NOT_FOUND", { message: "Изделие не найдено или снято с продажи" });
  }
  const wanted = new Set(optionIds);
  if (wanted.size !== optionIds.length) throw ctx.error("OPTION_INVALID", { message: "Опция выбрана дважды" });

  const available = await ctx.db.product_option.list({ where: { product: productId }, limit: 1000 });
  const picked = available.filter((o) => wanted.has(o.id) && o.active !== false);
  if (picked.length !== wanted.size) {
    throw ctx.error("OPTION_INVALID", { message: "Одна из опций недоступна для этого изделия" });
  }

  const missing: OptionGroup[] = [];
  for (const group of GROUPS) {
    const n = picked.filter((o) => o.option_group === group).length;
    if (n > 1 && REQUIRED[group]) throw ctx.error("OPTION_INVALID", { message: `${REQUIRED[group]}: только один вариант` });
    if (n === 0 && REQUIRED[group]) missing.push(group);
  }

  const rank = (o: Option) => GROUPS.indexOf(o.option_group) * 1e6 + (o.sort_order ?? 0);
  const lines = picked
    .sort((a, b) => rank(a) - rank(b))
    .map((o) => ({ id: o.id, group: o.option_group, title: o.title, price: o.price }));
  const totalKop = lines.reduce((s, l) => s + toKop(l.price), 0);
  const prepayKop = Math.ceil(totalKop / 2);
  return {
    lines,
    missing,
    total: totalKop / 100,
    prepay: prepayKop / 100,
    remaining: (totalKop - prepayKop) / 100,
  };
}

/** Текст первой ошибки выбора для ctx.error. */
export function missingMessage(missing: readonly OptionGroup[]): string {
  return missing.map((g) => REQUIRED[g]).find((m) => m) ?? "Выберите опции";
}

import type { ClientDoc, Json } from "@wizard/sdk";

type Order = ClientDoc<"cake_order">;
type Tone = "neutral" | "accent" | "ok" | "warn" | "bad";

export const STATUS: Record<Order["status"], { label: string; tone: Tone }> = {
  pending_payment: { label: "Ожидает предоплаты", tone: "warn" },
  prepaid: { label: "Предоплачен", tone: "accent" },
  in_production: { label: "В работе", tone: "accent" },
  ready: { label: "Готов к выдаче", tone: "ok" },
  completed: { label: "Выдан", tone: "neutral" },
  canceled: { label: "Отменён", tone: "bad" },
  refunded: { label: "Возвращён", tone: "bad" },
};

export const FULFILLMENT: Record<Order["fulfillment"], string> = { pickup: "Самовывоз", delivery: "Доставка" };

const money = new Intl.NumberFormat("ru-RU", { style: "currency", currency: "RUB", maximumFractionDigits: 2 });
const day = new Intl.DateTimeFormat("ru-RU", { weekday: "short", day: "numeric", month: "long", timeZone: "UTC" });

export const rub = (v: number): string => money.format(v);
/** YYYY-MM-DD → «сб, 11 октября». */
export const dayLabel = (date: string): string => day.format(new Date(`${date}T00:00:00Z`));

/** Снимок опций заказа (placeOrder.options) → «2,5 кг · Вишня–шоколад · Ягоды». */
export function optionsText(options: Json): string {
  if (!Array.isArray(options)) return "";
  return options
    .map((o) => (o && typeof o === "object" && !Array.isArray(o) && typeof o.title === "string" ? o.title : ""))
    .filter(Boolean)
    .join(" · ");
}

import { query, v } from "@wizard/sdk";
import { quote } from "./lib/pricing";

// Конфигуратор пересчитывает цену на каждый выбор; неполный выбор — не ошибка, а список missing.
export default query({
  args: {
    productId: v.id("product"),
    optionIds: v.array(v.id("product_option"), { max: 30 }),
  },
  handler: async (ctx, { productId, optionIds }) => {
    const q = await quote(ctx, productId, optionIds);
    return { total: q.total, prepay: q.prepay, remaining: q.remaining, missing: q.missing, lines: q.lines };
  },
});

import { query, v } from "@wizard/sdk";
import { moscowDate, taken } from "./lib/load";

// Производственные дни с сегодняшнего (по Москве) на `days` вперёд: ёмкость, занято, свободно.
// Нужна и конфигуратору (выбор даты), и доске производства (загрузка).
export default query({
  args: { days: v.optional(v.int({ min: 1, max: 60 })) },
  handler: async (ctx, { days = 30 }) => {
    const slots = await ctx.db.production_slot.list({
      where: { slot_date: { gte: moscowDate(ctx.now), lte: moscowDate(ctx.now, days - 1) } },
      limit: 100,
    });
    return Promise.all(
      slots.map(async (s) => {
        const busy = await taken(ctx, s.id);
        const closed = s.closed === true;
        return {
          id: s.id,
          date: s.slot_date,
          capacity: s.capacity,
          taken: busy,
          closed,
          free: closed ? 0 : Math.max(s.capacity - busy, 0),
        };
      }),
    );
  },
});

import { mutation, v } from "@wizard/sdk";
import { taken } from "./lib/load";
import { missingMessage, quote } from "./lib/pricing";

// SERIALIZABLE-транзакция: две гонки за последний торт дня не пройдут обе, runtime повторит handler.
// У покупателя нет права create на cake_order: сумму и номер ставит только эта функция, запись — через systemDb.
// Оплата предоплаты — отдельно, usePayment("yookassa").pay("prepay", orderId) по биндингу из AppSpec.
export default mutation({
  args: {
    productId: v.id("product"),
    optionIds: v.array(v.id("product_option"), { max: 30 }),
    slotId: v.id("production_slot"),
    fulfillment: v.enum("pickup", "delivery"),
    customerName: v.string({ min: 2, max: 120 }),
    customerPhone: v.phone(),
    customerEmail: v.optional(v.email()),
    address: v.optional(v.string({ max: 300 })),
    inscription: v.optional(v.string({ max: 60 })),
    note: v.optional(v.string({ max: 1000 })),
  },
  handler: async (ctx, a) => {
    const userId = ctx.user.id;
    if (!userId) throw ctx.error("UNAUTHENTICATED", { message: "Войдите, чтобы оформить заказ" });

    const price = await quote(ctx, a.productId, a.optionIds);
    if (price.missing.length > 0) throw ctx.error("OPTION_REQUIRED", { message: missingMessage(price.missing) });
    const address = a.address?.trim() || null;
    if (a.fulfillment === "delivery" && !address) {
      throw ctx.error("ADDRESS_REQUIRED", { message: "Укажите адрес доставки" });
    }

    const slot = await ctx.db.production_slot.get(a.slotId);
    if (!slot) throw ctx.error("NOT_FOUND", { message: "Дата готовности не найдена" });
    if (slot.closed) throw ctx.error("SLOT_CLOSED", { message: "В этот день кондитерская не работает" });
    if ((await taken(ctx, slot.id)) >= slot.capacity) {
      throw ctx.error("SLOT_FULL", { message: "На этот день производство загружено полностью, выберите другую дату" });
    }

    const last = await ctx.systemDb.cake_order.first({ where: { number: { gte: 1 } }, order: "desc" });
    const number = (last?.number ?? 0) + 1;
    const orderId = await ctx.systemDb.cake_order.insert({
      number,
      customer_user: userId,
      product: a.productId,
      options: price.lines.map((l) => ({ id: l.id, group: l.group, title: l.title, price: l.price })),
      inscription: a.inscription?.trim() || null,
      slot: slot.id,
      fulfillment: a.fulfillment,
      customer_name: a.customerName.trim(),
      customer_phone: a.customerPhone,
      customer_email: a.customerEmail ?? null,
      address: a.fulfillment === "delivery" ? address : null,
      total: price.total,
      prepay_amount: price.prepay,
      remaining_amount: price.remaining,
      status: "pending_payment",
      note: a.note?.trim() || null,
    });
    ctx.log.info("order_placed", { number, total: price.total });
    return { orderId, number, total: price.total, prepay: price.prepay, remaining: price.remaining };
  },
});

import { type ClientDoc, type Id, useEntityList, useMutation, usePayment, useQuery, useState, useUser } from "@wizard/sdk";
import { AppShell, Badge, Button, Catalog, ConsentCheckbox, Field, ItemCard } from "@wizard/ui-kit";
import { dayLabel, rub } from "./components/format";

type Product = ClientDoc<"product">;
type Group = ClientDoc<"product_option">["option_group"];
type Selection = Record<string, string[]>;

const GROUPS: { id: Group; label: string; kind: "single" | "multi"; required: boolean }[] = [
  { id: "weight", label: "Вес", kind: "single", required: true },
  { id: "filling", label: "Начинка", kind: "single", required: true },
  { id: "decor", label: "Декор", kind: "multi", required: false },
];

export default function Configurator() {
  const [product, setProduct] = useState<Product | null>(null);
  return (
    <AppShell>
      {product ? (
        <CakeBuilder product={product} onBack={() => setProduct(null)} />
      ) : (
        <Catalog
          entity="product"
          query={{ filter: { active: true }, sort: { field: "name", dir: "asc" } }}
          map={(p: Product) => ({
            id: p.id,
            title: p.name,
            description: p.description ?? undefined,
            price: null,
            priceText: "цена зависит от веса и декора",
          })}
          onSelect={(p: Product) => setProduct(p)}
          emptyText="Скоро здесь появятся торты"
        />
      )}
    </AppShell>
  );
}

// Опции — из product_option этого изделия; итог и предоплата — только из calcPrice (сервер), не из суммы чипов.
function CakeBuilder({ product, onBack }: { product: Product; onBack: () => void }) {
  const { user, login } = useUser();
  const options = useEntityList("product_option", {
    filter: { product: product.id, active: true },
    sort: ["option_group", "sort_order"],
    limit: 100,
  });
  const [selection, setSelection] = useState<Selection>({});
  const [ordering, setOrdering] = useState(false);
  const optionIds = Object.values(selection).flat() as Id<"product_option">[];
  const price = useQuery("calcPrice", { productId: product.id, optionIds });
  const ready = price.data !== undefined && price.data.missing.length === 0;

  const optionGroups = GROUPS.map((g) => ({
    ...g,
    choices: options.items
      .filter((o) => o.option_group === g.id)
      .map((o) => ({ id: o.id, label: o.title, priceDelta: o.price })),
  })).filter((g) => g.choices.length > 0);

  return (
    <>
      <ItemCard
        id={product.id}
        title={product.name}
        description={product.description ?? undefined}
        price={null}
        priceText={price.data ? `Предоплата 50%: ${rub(price.data.prepay)}` : "Соберите торт"}
        optionGroups={optionGroups}
        selection={selection}
        onSelectionChange={(s: Selection) => {
          setSelection(s);
          setOrdering(false);
        }}
        total={price.data?.total}
        ctaLabel="Оформить предзаказ"
        disabled={!ready}
        onCta={() => (user ? setOrdering(true) : login({ role: "customer", next: "/" }))}
      />
      {price.error && <Badge tone="bad">{price.error.details.message ?? "Не удалось посчитать цену"}</Badge>}
      {ordering && user && user.role !== "customer" && (
        <Badge tone="warn">Заказ оформляет покупатель: войдите под его учётной записью</Badge>
      )}
      {ordering && user?.role === "customer" && price.data && (
        <OrderForm
          productId={product.id}
          optionIds={optionIds}
          prepay={price.data.prepay}
          remaining={price.data.remaining}
          hasInscription={price.data.lines.some((l) => l.group === "decor")}
          defaultName={user.displayName}
          onCancel={() => setOrdering(false)}
        />
      )}
      <Button variant="ghost" onClick={onBack}>
        Ко всем тортам
      </Button>
    </>
  );
}

// Форма без RecordForm: заказ создаёт placeOrder (цена, загрузка дня, номер), затем — предоплата через ЮKassa.
function OrderForm(props: {
  productId: Id<"product">;
  optionIds: Id<"product_option">[];
  prepay: number;
  remaining: number;
  hasInscription: boolean;
  defaultName: string;
  onCancel: () => void;
}) {
  const slots = useQuery("freeSlots", {});
  const [place, placing] = useMutation("placeOrder");
  const payment = usePayment("yookassa");
  const [form, setForm] = useState({
    slotId: "",
    fulfillment: "pickup",
    customerName: props.defaultName,
    customerPhone: "",
    customerEmail: "",
    address: "",
    inscription: "",
    note: "",
    consent: false,
  });
  const set = (k: keyof typeof form) => (v: unknown) => setForm({ ...form, [k]: v });
  const delivery = form.fulfillment === "delivery";
  const open = (slots.data ?? []).filter((s) => s.free > 0);

  const submit = async () => {
    const res = await place(
      {
        productId: props.productId,
        optionIds: props.optionIds,
        slotId: form.slotId as Id<"production_slot">,
        fulfillment: delivery ? "delivery" : "pickup",
        customerName: form.customerName,
        customerPhone: form.customerPhone,
        customerEmail: form.customerEmail || undefined,
        address: delivery ? form.address : undefined,
        inscription: form.inscription || undefined,
        note: form.note || undefined,
      },
      { consent: true },
    );
    await payment.pay("prepay", res.orderId);
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (form.consent) void submit();
      }}
    >
      <Field
        name="slotId"
        label="Дата готовности"
        type="enum"
        required
        value={form.slotId}
        onChange={set("slotId")}
        enumOptions={open.map((s) => ({ value: s.id, label: `${dayLabel(s.date)} · свободно ${s.free}` }))}
        hint={slots.data && open.length === 0 ? "Свободных дней нет — загляните позже" : undefined}
      />
      <Field
        name="fulfillment"
        label="Получение"
        type="enum"
        required
        value={form.fulfillment}
        onChange={set("fulfillment")}
        enumOptions={[
          { value: "pickup", label: "Самовывоз" },
          { value: "delivery", label: "Доставка" },
        ]}
      />
      {delivery && (
        <Field name="address" label="Адрес доставки" type="string" required maxLength={300} value={form.address} onChange={set("address")} />
      )}
      {props.hasInscription && (
        <Field name="inscription" label="Надпись на торте" type="string" maxLength={60} value={form.inscription} onChange={set("inscription")} />
      )}
      <Field name="customerName" label="Имя" type="string" required maxLength={120} value={form.customerName} onChange={set("customerName")} />
      <Field name="customerPhone" label="Телефон" type="phone" required value={form.customerPhone} onChange={set("customerPhone")} />
      <Field
        name="customerEmail"
        label="Email для чека"
        type="email"
        hint="Чек придёт на почту; без неё — по SMS на телефон"
        value={form.customerEmail}
        onChange={set("customerEmail")}
      />
      <Field name="note" label="Комментарий" type="text" maxLength={1000} value={form.note} onChange={set("note")} />
      <Badge tone="accent">{`Сейчас — предоплата ${rub(props.prepay)}, при получении — ${rub(props.remaining)}`}</Badge>
      <ConsentCheckbox checked={form.consent} onChange={set("consent")} />
      {placing.error && <Badge tone="bad">{placing.error.details.message ?? "Не удалось оформить заказ"}</Badge>}
      {payment.error && <Badge tone="bad">{payment.error.details.message ?? "Не удалось перейти к оплате"}</Badge>}
      <Button
        type="submit"
        variant="primary"
        loading={placing.pending || payment.pending}
        disabled={!form.consent || !form.slotId}
      >
        Оплатить предоплату
      </Button>
      <Button variant="ghost" onClick={props.onCancel}>
        Отмена
      </Button>
    </form>
  );
}

import { type ClientDoc, useEntityList, usePayment, useQuery } from "@wizard/sdk";
import { AppShell, Badge, ItemCard } from "@wizard/ui-kit";
import { dayLabel, FULFILLMENT, optionsText, rub, STATUS } from "./components/format";

type Order = ClientDoc<"cake_order">;

// Покупатель видит только свои заказы: rowFilter customer_user = $user.id применяет data API, не страница.
// Оплата — биндинги ЮKassa из AppSpec: «prepay» в статусе pending_payment, «final» — когда торт готов.
export default function MyOrders() {
  const orders = useEntityList("cake_order", { sort: "-created_at", limit: 50 });
  const slots = useQuery("freeSlots", { days: 60 });
  const payment = usePayment("yookassa");
  const dates = new Map(slots.data?.map((s) => [s.id, s.date]));

  const cta = (o: Order) => {
    if (o.status === "pending_payment") return { label: `Внести предоплату ${rub(o.prepay_amount)}`, pay: () => payment.pay("prepay", o.id) };
    if (o.status === "ready") return { label: `Доплатить ${rub(o.remaining_amount)}`, pay: () => payment.pay("final", o.id) };
    return { label: o.status === "completed" ? "Заказ выдан" : "Оплата не требуется", pay: null };
  };

  return (
    <AppShell title="Мои заказы">
      {!orders.isLoading && orders.items.length === 0 && <Badge tone="neutral">Заказов пока нет — соберите торт на главной</Badge>}
      {payment.error && <Badge tone="bad">{payment.error.details.message ?? "Не удалось перейти к оплате"}</Badge>}
      {orders.items.map((o) => {
        const action = cta(o);
        const date = dates.get(o.slot);
        return (
          <ItemCard
            key={o.id}
            id={o.id}
            title={`Заказ №${o.number}`}
            description={[
              optionsText(o.options),
              o.inscription ? `надпись «${o.inscription}»` : "",
              `${FULFILLMENT[o.fulfillment]}${date ? `, ${dayLabel(date)}` : ""}`,
            ]
              .filter(Boolean)
              .join(" · ")}
            price={o.total}
            badge={{ text: STATUS[o.status].label, tone: STATUS[o.status].tone }}
            ctaLabel={action.label}
            disabled={!action.pay || payment.pending}
            onCta={() => void action.pay?.()}
          />
        );
      })}
    </AppShell>
  );
}

import { type ClientDoc, useQuery, useState } from "@wizard/sdk";
import { AppShell, Button, RecordCard, StatsReport, StatusBoard } from "@wizard/ui-kit";
import { dayLabel, FULFILLMENT, optionsText } from "./components/format";

type Order = ClientDoc<"cake_order">;

// Доска производства: перенос между колонками — update status с правами роли (у кондитера суммы, состав
// и контакты заказа — readonly). Уведомления «принят»/«готов» шлют воркфлоу order_prepaid/order_ready.
export default function Production() {
  const slots = useQuery("freeSlots", { days: 14 });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const days = slots.data ?? [];
  const dates = new Map(days.map((s) => [s.id, s.date]));
  const sum = (k: "capacity" | "taken" | "free") => days.reduce((n, s) => n + s[k], 0);

  return (
    <AppShell title="Производство">
      <StatsReport
        title="Загрузка на две недели"
        data={{
          kpis: [
            { id: "taken", label: "Тортов в заказах", value: sum("taken"), total: sum("capacity"), format: "int" },
            { id: "free", label: "Свободных мест", value: sum("free"), format: "int" },
          ],
          bars: {
            title: "По дням",
            items: days.filter((s) => !s.closed).map((s) => ({ label: dayLabel(s.date), value: s.taken, max: s.capacity })),
          },
        }}
      />
      <StatusBoard
        entity="cake_order"
        statusField="status"
        columns={["prepaid", "in_production", "ready", "completed"]}
        card={(o: Order) => {
          const date = dates.get(o.slot);
          return {
            title: `№${o.number} · ${optionsText(o.options)}`,
            subtitle: o.inscription ? `Надпись: «${o.inscription}»` : undefined,
            meta: `${FULFILLMENT[o.fulfillment]}${date ? ` · к ${dayLabel(date)}` : ""}`,
          };
        }}
        onCardClick={(o: Order) => setSelectedId(o.id)}
        limitPerColumn={30}
      />
      {selectedId && (
        <>
          <RecordCard
            entity="cake_order"
            id={selectedId}
            fields={["number", "status", "inscription", "note", "fulfillment", "address", "customer_name", "customer_phone", "total", "remaining_amount"]}
            title={(o: Order) => `Заказ №${o.number}`}
            actions={[
              { id: "start", label: "Взять в работу", tone: "primary", kind: "update", patch: { status: "in_production" }, visible: (o: Order) => o.status === "prepaid" },
              { id: "ready", label: "Готов к выдаче", tone: "primary", kind: "update", patch: { status: "ready" }, visible: (o: Order) => o.status === "in_production" },
              {
                id: "handed",
                label: "Выдан, доплата получена",
                kind: "update",
                patch: { status: "completed" },
                confirm: "Покупатель доплатил на месте и забрал заказ?",
                visible: (o: Order) => o.status === "ready",
              },
            ]}
          />
          <Button variant="ghost" onClick={() => setSelectedId(null)}>
            Закрыть
          </Button>
        </>
      )}
    </AppShell>
  );
}

import { type ClientDoc, useState } from "@wizard/sdk";
import { Button, CabinetLayout, DataTable, RecordForm } from "@wizard/ui-kit";

type Product = ClientDoc<"product">;
type Option = ClientDoc<"product_option">;
type Slot = ClientDoc<"production_slot">;

// Кабинет владельца: справочники через data API (права owner — полные). Фото (file) в эталоне не редактируется
// (поле не перечислено в fields); загрузка файлов — FileField/RecordForm с M2-14 (runtime.yaml#files).
export default function CatalogAdmin() {
  return (
    <CabinetLayout
      title="Изделия и опции"
      defaultSection="products"
      sections={[
        { id: "products", label: "Изделия", content: <Products /> },
        { id: "options", label: "Опции и цены", content: <Options /> },
        { id: "slots", label: "Производственные дни", content: <Slots /> },
      ]}
    />
  );
}

/** Таблица + форма: клик по строке — редактирование, кнопка — новая запись. */
function useEditor() {
  const [editing, setEditing] = useState<string | "new" | null>(null);
  return {
    editing,
    open: (id: string | "new") => setEditing(id),
    close: () => setEditing(null),
  };
}

function Products() {
  const ed = useEditor();
  return (
    <>
      <DataTable
        entity="product"
        columns={["name", "active", "created_at"]}
        defaultSort={{ field: "name", dir: "asc" }}
        searchable
        onRowClick={(p: Product) => ed.open(p.id)}
        emptyText="Изделий пока нет"
      />
      {ed.editing ? (
        <RecordForm
          key={ed.editing}
          entity="product"
          mode={ed.editing === "new" ? "create" : "edit"}
          id={ed.editing === "new" ? undefined : ed.editing}
          fields={["name", "description", "active"]}
          onSuccess={ed.close}
          onCancel={ed.close}
        />
      ) : (
        <Button variant="secondary" onClick={() => ed.open("new")}>
          Добавить изделие
        </Button>
      )}
    </>
  );
}

// Цена опции веса — базовая цена торта, остальные группы — надбавки (functions/lib/pricing.ts).
function Options() {
  const ed = useEditor();
  return (
    <>
      <DataTable
        entity="product_option"
        columns={["product", "option_group", "title", "price", "weight_kg", "sort_order", "active"]}
        defaultSort={{ field: "sort_order", dir: "asc" }}
        filters={["product", "option_group", "active"]}
        onRowClick={(o: Option) => ed.open(o.id)}
        emptyText="Опций пока нет"
      />
      {ed.editing ? (
        <RecordForm
          key={ed.editing}
          entity="product_option"
          mode={ed.editing === "new" ? "create" : "edit"}
          id={ed.editing === "new" ? undefined : ed.editing}
          fields={["product", "option_group", "title", "price", "weight_kg", "sort_order", "active"]}
          onSuccess={ed.close}
          onCancel={ed.close}
        />
      ) : (
        <Button variant="secondary" onClick={() => ed.open("new")}>
          Добавить опцию
        </Button>
      )}
    </>
  );
}

function Slots() {
  const ed = useEditor();
  return (
    <>
      <DataTable
        entity="production_slot"
        columns={["slot_date", "capacity", "closed"]}
        defaultSort={{ field: "slot_date", dir: "asc" }}
        onRowClick={(s: Slot) => ed.open(s.id)}
        emptyText="Откройте производственные дни, чтобы покупатели могли выбрать дату"
      />
      {ed.editing ? (
        <RecordForm
          key={ed.editing}
          entity="production_slot"
          mode={ed.editing === "new" ? "create" : "edit"}
          id={ed.editing === "new" ? undefined : ed.editing}
          fields={["slot_date", "capacity", "closed"]}
          defaults={{ capacity: 5 }}
          onSuccess={ed.close}
          onCancel={ed.close}
        />
      ) : (
        <Button variant="secondary" onClick={() => ed.open("new")}>
          Добавить день
        </Button>
      )}
    </>
  );
}
